const KEYWORDS = ['block', 'group', 'note', '@canvas', '@include'];
const BOX_FORM = { block: 'block ID "ラベル" at X,Y size WxH', group: 'group ID "ラベル" at X,Y size WxH', note: 'note ID "テキスト" at X,Y size WxH' };

