    const m = String(rest || '').match(new RegExp(`${attr}=(\\S+)`));
    if (m && !values.includes(m[1])) out.push({ attr, value: m[1], msg: `${attr}=${m[1]} は使えない。${fallback}(使える値: ${values.join(' / ')})` });
